/* T9-K0: checks and lookup-work measurements for the production packed
 * dictionary (keymap/t9_dictionary_data.h, generated by `make dict`).
 *
 * SPDX-License-Identifier: GPL-2.0-or-later
 */
#include <stdio.h>
#include <string.h>
#include "t9_dict_packed.h"
#include "t9_test.h"
#include "t9_dictionary_data.h"

/* CHECK with a printf-style explanation on failure */
#define CHECK_MSG(cond, ...)             \
    do {                                 \
        if (!CHECK(cond)) {              \
            printf("     " __VA_ARGS__); \
            putchar('\n');               \
        }                                \
    } while (0)

typedef struct {
    char word[T9_MAX_WORD_LEN + 1];
    uint8_t len;
    uint8_t score;
} decoded_entry_t;

static decoded_entry_t entries[T9_DICT_WORD_COUNT];

static uint32_t read_field(uint32_t *pos, uint8_t width) {
    uint32_t value = 0;
    for (uint8_t i = 0; i < width; i++, (*pos)++)
        value = (value << 1) | ((t9_dict_bits[*pos >> 3] >> (7 - (*pos & 7))) & 1);
    return value;
}

/* <0, 0, >0 in documented dictionary order */
static int compare_entries(const decoded_entry_t *a, const decoded_entry_t *b) {
    for (uint8_t i = 0; i < a->len && i < b->len; i++) {
        int diff = t9_letter_digit(a->word[i]) - t9_letter_digit(b->word[i]);
        if (diff)
            return diff;
    }
    if (a->len != b->len)
        return a->len - b->len;
    if (a->score != b->score)
        return b->score - a->score;
    return strcmp(a->word, b->word);
}

static bool same_sequence(const decoded_entry_t *a, const decoded_entry_t *b) {
    if (a->len != b->len)
        return false;
    for (uint8_t i = 0; i < a->len; i++) {
        if (t9_letter_digit(a->word[i]) != t9_letter_digit(b->word[i]))
            return false;
    }
    return true;
}

static void test_index(void) {
    uint32_t total_bits = t9_dict_block_offsets[T9_DICT_BLOCK_COUNT];
    CHECK_MSG(t9_dict_block_offsets[0] == 0, "first block offset %u", (unsigned)t9_dict_block_offsets[0]);
    for (uint32_t b = 0; b < T9_DICT_BLOCK_COUNT; b++)
        CHECK_MSG(t9_dict_block_offsets[b] < t9_dict_block_offsets[b + 1], "block offsets not increasing at %u",
                  (unsigned)b);
    CHECK_MSG((total_bits + 7) / 8 == sizeof(t9_dict_bits), "total bits %u vs %u bitstream bytes", (unsigned)total_bits,
              (unsigned)sizeof(t9_dict_bits));
    CHECK_MSG(T9_DICT_BLOCK_COUNT == (T9_DICT_WORD_COUNT + T9_DICT_BLOCK_SIZE - 1) / T9_DICT_BLOCK_SIZE,
              "block count %u", (unsigned)T9_DICT_BLOCK_COUNT);
    CHECK_MSG(
        T9_DICT_DATA_BYTES == sizeof(t9_dict_bits) + sizeof(t9_dict_block_offsets) + sizeof(t9_dict_block_max_score),
        "T9_DICT_DATA_BYTES disagrees with the arrays");
}

/* sequential decode of every entry, independent of the decoder under test */
static void test_full_decode(void) {
    uint32_t pos = 0;
    uint8_t sequence[T9_MAX_WORD_LEN];
    uint8_t block_max = 0;
    for (uint32_t i = 0; i < T9_DICT_WORD_COUNT; i++) {
        uint32_t block = i / T9_DICT_BLOCK_SIZE;
        if (i % T9_DICT_BLOCK_SIZE == 0) {
            CHECK_MSG(pos == t9_dict_block_offsets[block], "entry %u starts at bit %u, index says %u", (unsigned)i,
                      (unsigned)pos, (unsigned)t9_dict_block_offsets[block]);
            block_max = 0;
        }
        decoded_entry_t *entry = &entries[i];
        uint8_t shared         = (uint8_t)read_field(&pos, 5);
        entry->len             = (uint8_t)read_field(&pos, 5);
        CHECK_MSG(entry->len >= 1 && entry->len <= T9_MAX_WORD_LEN, "entry %u: length %u", (unsigned)i, entry->len);
        CHECK_MSG(shared <= entry->len && (i % T9_DICT_BLOCK_SIZE == 0 ? shared == 0 : shared <= entries[i - 1].len),
                  "entry %u: shared %u", (unsigned)i, shared);
        if (entry->len < 1 || entry->len > T9_MAX_WORD_LEN || shared > entry->len)
            return;
        for (uint8_t d = shared; d < entry->len; d++)
            sequence[d] = (uint8_t)(read_field(&pos, 3) + 2);
        for (uint8_t l = 0; l < entry->len; l++) {
            uint8_t index = (uint8_t)read_field(&pos, 2);
            CHECK_MSG(index < strlen(t9_digit_letters[sequence[l]]), "entry %u: letter index %u for digit %u",
                      (unsigned)i, index, sequence[l]);
            entry->word[l] = t9_digit_letters[sequence[l]][index];
        }
        entry->word[entry->len] = 0;
        entry->score            = (uint8_t)read_field(&pos, 6);
        if (entry->score > block_max)
            block_max = entry->score;
        if (i > 0)
            CHECK_MSG(compare_entries(&entries[i - 1], entry) < 0, "entries %u and %u out of order: %s, %s",
                      (unsigned)i - 1, (unsigned)i, entries[i - 1].word, entry->word);
        if (i % T9_DICT_BLOCK_SIZE == T9_DICT_BLOCK_SIZE - 1 || i == T9_DICT_WORD_COUNT - 1)
            CHECK_MSG(block_max == t9_dict_block_max_score[block], "block %u max score %u, decoded %u", (unsigned)block,
                      t9_dict_block_max_score[block], block_max);
    }
    CHECK_MSG(pos == t9_dict_block_offsets[T9_DICT_BLOCK_COUNT], "decode ends at bit %u, index says %u", (unsigned)pos,
              (unsigned)t9_dict_block_offsets[T9_DICT_BLOCK_COUNT]);
}

static uint8_t text_digits(const char *text, uint8_t *digits) {
    uint8_t len = 0;
    for (; text[len]; len++)
        digits[len] = (uint8_t)(text[len] - '0');
    return len;
}

typedef struct {
    const char *digits;
    bool expect_exact;
} common_sequence_t;

static void test_common_sequences(void) {
    static const common_sequence_t common[] = {
        {"4663", true}, {"43556", true}, {"2", true},     {"22", false}, {"7", false}, {"843", true},
        {"96", true},   {"4", true},     {"63", true},    {"86", true},  {"46", true}, {"28", true},
        {"9675", true}, {"8447", true},  {"7464", false}, {"66", false},
    };
    printf("  common sequences (top candidates; entries decoded, blocks skipped):\n");
    for (size_t c = 0; c < sizeof(common) / sizeof(common[0]); c++) {
        uint8_t digits[T9_MAX_WORD_LEN];
        uint8_t len = text_digits(common[c].digits, digits);
        t9_candidates_t list;
        t9_dict_packed_reset_counters();
        t9_dict_packed_lookup(digits, len, &list);
        CHECK_MSG(list.count > 0, "%s: no candidates", common[c].digits);
        if (common[c].expect_exact)
            CHECK_MSG(list.total_exact > 0, "%s: no exact word", common[c].digits);
        printf("    %-6s exact %3u total %3u:", common[c].digits, list.total_exact, list.count);
        for (uint8_t i = 0; i < list.count && i < 5; i++)
            printf(" %s", list.words[i]);
        printf("  (%u, %u)\n", (unsigned)t9_dict_packed_entries_decoded(), (unsigned)t9_dict_packed_blocks_skipped());
    }
}

typedef struct {
    uint32_t lookups;
    uint32_t worst_decoded;
    uint32_t worst_skipped;
    uint64_t sum_decoded;
    uint32_t buckets[6]; /* decoded < 64, 128, 256, 512, 1024, more */
    char worst_digits[T9_MAX_WORD_LEN + 1];
} work_t;

static void measure(work_t *work, const uint8_t *digits, uint8_t len, t9_candidates_t *list) {
    t9_dict_packed_reset_counters();
    t9_dict_packed_lookup(digits, len, list);
    uint32_t decoded = t9_dict_packed_entries_decoded();
    uint32_t skipped = t9_dict_packed_blocks_skipped();
    CHECK_MSG(decoded <= T9_DICT_WORD_COUNT, "decoded %u entries", (unsigned)decoded);
    work->lookups++;
    work->sum_decoded += decoded;
    if (skipped > work->worst_skipped)
        work->worst_skipped = skipped;
    if (decoded > work->worst_decoded) {
        work->worst_decoded = decoded;
        for (uint8_t i = 0; i < len; i++)
            work->worst_digits[i] = (char)('0' + digits[i]);
        work->worst_digits[len] = 0;
    }
    uint8_t bucket = 0;
    while (bucket < 5 && decoded >= (64u << bucket))
        bucket++;
    work->buckets[bucket]++;
}

static void print_work(const char *name, const work_t *work) {
    printf(
        "  %-28s lookups %6u  decoded avg %7.1f worst %5u (%s)  worst blocks skipped %4u  histogram <64:%u <128:%u "
        "<256:%u <512:%u <1024:%u more:%u\n",
        name, (unsigned)work->lookups, work->lookups ? (double)work->sum_decoded / work->lookups : 0.0,
        (unsigned)work->worst_decoded, work->worst_digits, (unsigned)work->worst_skipped, (unsigned)work->buckets[0],
        (unsigned)work->buckets[1], (unsigned)work->buckets[2], (unsigned)work->buckets[3], (unsigned)work->buckets[4],
        (unsigned)work->buckets[5]);
}

static void measure_prefixes(void) {
    work_t one = {0}, two = {0};
    t9_candidates_t list;
    for (uint8_t a = 2; a <= 9; a++) {
        measure(&one, (uint8_t[]){a}, 1, &list);
        for (uint8_t b = 2; b <= 9; b++)
            measure(&two, (uint8_t[]){a, b}, 2, &list);
    }
    print_work("1-digit prefixes", &one);
    print_work("2-digit prefixes", &two);
}

/* every exact sequence of 3-5 digits; total_exact and the best exact word checked against the decode */
static void measure_exact_sequences(void) {
    work_t work            = {0};
    uint32_t largest_group = 0;
    for (uint32_t start = 0; start < T9_DICT_WORD_COUNT;) {
        uint32_t end = start + 1;
        while (end < T9_DICT_WORD_COUNT && same_sequence(&entries[start], &entries[end]))
            end++;
        if (end - start > largest_group)
            largest_group = end - start;
        if (entries[start].len >= 3 && entries[start].len <= 5) {
            uint8_t digits[T9_MAX_WORD_LEN];
            for (uint8_t i = 0; i < entries[start].len; i++)
                digits[i] = t9_letter_digit(entries[start].word[i]);
            t9_candidates_t list;
            measure(&work, digits, entries[start].len, &list);
            uint8_t first_exact = 0;
            while (first_exact < list.count && strlen(list.words[first_exact]) != entries[start].len)
                first_exact++;
            CHECK_MSG(list.total_exact == end - start && end - start <= T9_MAX_EXACT && first_exact < list.count &&
                          strcmp(list.words[first_exact], entries[start].word) == 0,
                      "%s: exact %u (expected %u), best exact '%s'", entries[start].word, list.total_exact,
                      (unsigned)(end - start), first_exact < list.count ? list.words[first_exact] : "");
        }
        start = end;
    }
    print_work("exact sequences, 3-5 digits", &work);
    printf("  largest exact collision: %u words\n", (unsigned)largest_group);
}

/* Exact words must survive the engine's filtering as well as dictionary lookup. */
static void test_fox_is_reachable(void) {
    for (int completions = 0; completions < 2; completions++) {
        for (int clockwise = 0; clockwise < 2; clockwise++) {
            for (int queued = 0; queued < 2; queued++) {
                static t9_rig_t r;
                rig_init(&r, t9_dict_packed_lookup);
                r.engine.mode = T9_MODE_T9;
                CHECK(t9_set_completions(&r.engine, completions));
                r.auto_drain = !queued;
                rig_type(&r, "369");
                bool found = false;
                for (uint8_t i = 0; i < r.engine.cands.count; i++) {
                    if (strncmp(t9_preview(&r.engine), "fox", 3) == 0) {
                        found = true;
                        break;
                    }
                    CHECK(rig_dial(&r, clockwise));
                }
                CHECK(found);
                if (!found)
                    continue;
                rig_type(&r, "cc"); /* switching completions preserves the chosen base */
                CHECK(strncmp(t9_preview(&r.engine), "fox", 3) == 0);
                rig_type(&r, "0");
                CHECK_STR(rig_drain(&r), "fox ");
                CHECK(!t9_is_composing(&r.engine));
            }
        }
    }
}

static void test_complete_words_first(void) {
    static const struct {
        const char *digits, *base, *suggestion;
    } cases[] = {
        {"364", "dog", "doi[ng]"},      {"369", "fox", "dow[n]"},       {"937", "yes", "wer[e]"},
        {"63342", "media", "offic[e]"}, {"23446", "begin", "behin[d]"}, {"4663", "good", "good[s]"},
    };
    for (int completions = 0; completions < 2; completions++) {
        for (int queued = 0; queued < 2; queued++) {
            for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
                static t9_rig_t r;
                rig_init(&r, t9_dict_packed_lookup);
                CHECK(t9_set_completions(&r.engine, completions));
                r.auto_drain = !queued;
                rig_type(&r, cases[i].digits);
                CHECK_STR(rig_drain(&r), completions ? cases[i].suggestion : cases[i].base);
                if (!completions) {
                    CHECK_INT(r.engine.cand_index, 0);
                    CHECK(r.engine.cands.total_exact > 0);
                }
            }
        }
    }
}

static void test_prefix_family_completion(void) {
    static const struct {
        const char *digits, *preview, *next, *word, *plural;
    } cases[] = {
        {"53926", "keybo>ard", "keyboard>s", "keyboard ", "keyboards "},
        {"466329", "goodby>e", "goodbye>s", "goodbye ", "goodbyes "},
        {"73675", "peopl>e", "people>s", "people ", "peoples "},
    };
    for (int queued = 0; queued < 2; queued++) {
        for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++) {
            for (int plural = 0; plural < 2; plural++) {
                static t9_rig_t r;
                rig_init(&r, t9_dict_packed_lookup);
                r.auto_drain = !queued;
                rig_type(&r, cases[i].digits);
                CHECK_STR(t9_preview(&r.engine), cases[i].preview);
                CHECK(t9_has_completion(&r.engine));
                rig_type(&r, "e");
                CHECK_STR(t9_preview(&r.engine), cases[i].next);
                CHECK(t9_is_composing(&r.engine));
                rig_type(&r, plural ? "e" : "0");
                CHECK_STR(rig_drain(&r), plural ? cases[i].plural : cases[i].word);
                CHECK(!t9_is_composing(&r.engine));
            }
        }
    }
}

int main(void) {
    const t9_dict_packed_stats_t *stats = t9_dict_packed_stats();
    printf(
        "t9_dict_production_test: %u words, %u blocks of %u, %u data bytes (%.3f B/word, %.2f bits/word in the "
        "bitstream)\n",
        (unsigned)stats->word_count, (unsigned)stats->block_count, (unsigned)stats->block_size,
        (unsigned)stats->data_bytes, (double)stats->data_bytes / stats->word_count,
        (double)t9_dict_block_offsets[T9_DICT_BLOCK_COUNT] / stats->word_count);
    test_index();
    test_full_decode();
    if (t9_test_failures == 0) {
        test_common_sequences();
        measure_prefixes();
        measure_exact_sequences();
        test_fox_is_reachable();
        test_complete_words_first();
        test_prefix_family_completion();
    }
    return t9_test_summary("t9_dict_production_test");
}
